import React, {useEffect, useState } from 'react';
import TotalSalesChart from './TotalSalesChart';
import TotalCustomersChart from './TotalCustomersChart';
import './report.css';
import { getProducts } from '../data/dataFetching';

function Report() {

    const [products, setProducts] = useState([]);
           
        useEffect(() => {
            getProducts().then(data => setProducts(data));
            }, []);

  return (
    <>
    
        <div className='trend-holder'>

            <h1>Report</h1>

            <div className='popular-products-container' >
                
                { products.length > 0 &&
                    <div className='popular-product-column'>
                        <h3>Week popular</h3>
                        <i className={products[0].product_picture + ' bi popular-product-picture'} ></i>
                        <h5>{products[0].name}</h5>
                        

                    </div>
                }

                { products.length > 1 &&
                    <div className='popular-product-column'>
                        <h3>Month popular</h3>
                        <i className={products[1].product_picture + ' bi popular-product-picture'}></i>
                        <h5>{products[1].name}</h5>
                    </div>
                }

                { products.length > 2 &&
                
                    <div className='popular-product-column'>
                        <h3>Popular in { new Date().getFullYear()-1}</h3>
                        <i className={products[2].product_picture + ' bi popular-product-picture'}></i>
                        <h5>{products[2].name}</h5>
                    </div>
                
                }
                

            </div>

        </div>

        <div className='charts-holder'>

            <div className='chart-info mb-5'>

                <h3>Total Sales</h3>

                <TotalSalesChart />


            </div>

            <div className='chart-info mb-5'>

                <h3>Total Customers</h3>

                <TotalCustomersChart />


            </div>
        </div>
    
    </>
  )
}

export default Report;
